@rendermode InteractiveServer
@using sv_85d5d1b01e0c47b595f6c5b0205b9add.Components.Pages.Apply
@using sv_85d5d1b01e0c47b595f6c5b0205b9add.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="_currentStep"
                   CompletedUpTo="_completedUpTo"
                   OnStepSelected="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="_personalInfo"
                              ApplicationService="ApplicationService"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             CoverLetterChanged="UpdateCoverLetter"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="_personalInfo"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        ApplicationService="ApplicationService"
                        OnBack="PreviousStep"
                        OnEditSection="GoToStep" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private int _completedUpTo;

    private PersonalInfoModel _personalInfo = new();
    private List<WorkEntryModel> _workEntries = [new WorkEntryModel()];
    private List<ReferenceModel> _references = [new ReferenceModel(), new ReferenceModel()];
    private string _coverLetter = string.Empty;

    private void NextStep()
    {
        _currentStep++;
        if (_completedUpTo < _currentStep)
            _completedUpTo = _currentStep;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step <= _completedUpTo)
            _currentStep = step;
    }

    private void UpdateCoverLetter(string value)
    {
        _coverLetter = value;
    }
}

